$ErrorActionPreference = 'Stop'
# Privacy: Alibre stores the full path of the folder a document is saved to inside the document (VERSION, CONSTITUENTS,
# PROP_DATA and STEP_DATA streams), so nothing the run keeps may name the person running it. Everything printed or logged goes
# through Scrub, an uncaught error is printed scrubbed (volunteers screenshot the console), the output folder may not be a
# user's folder, every saved file is scanned, and at the end every file in the run folder is swept again.
# Text files are UTF-8 without a byte-order mark (Windows PowerShell 5.1's Set-Content with UTF8 writes one, and JSON readers refuse it).
$Utf8 = New-Object Text.UTF8Encoding $false
$Log = $null
# Private words (user name, profile folder name, computer name, domain, logon server) are matched as words only when long enough
# and not a common word (a user named "admin" or a computer named "pc" would match everywhere).
$PrivCommon = @('admin', 'administrator', 'user', 'users', 'owner', 'public', 'shared', 'guest', 'test', 'home', 'default', 'work', 'data', 'temp', 'office',
    'design', 'alibre', 'fixture', 'builder', 'step', 'part', 'workgroup', 'desktop', 'laptop', 'computer', 'server', 'domain', 'local', 'windows')
function PrivWordOk([string]$w) { return ($w.Length -ge 3 -and $PrivCommon -notcontains $w.ToLowerInvariant()) }
$PrivUser = [string]$env:USERNAME
$PrivUserOk = PrivWordOk $PrivUser
$PrivWords = @()
$profLeaf = if ($env:USERPROFILE) { Split-Path -Leaf (([string]$env:USERPROFILE).TrimEnd('\')) } else { '' }
foreach ($w in @($PrivUser, $profLeaf, $env:COMPUTERNAME, $env:USERDOMAIN, ([string]$env:LOGONSERVER).TrimStart('\'))) {
    $w = [string]$w; if ((PrivWordOk $w) -and -not ($PrivWords | Where-Object { $_ -ieq $w })) { $PrivWords += $w }
}
# Private folders: the profile, Documents and Desktop (often redirected: \\fs01\home$\bob\Documents, D:\Docs) and every OneDrive
$PrivRoots = @()
foreach ($r in @($env:USERPROFILE, $env:OneDrive, $env:OneDriveCommercial, $env:OneDriveConsumer, [Environment]::GetFolderPath('MyDocuments'), [Environment]::GetFolderPath('Desktop'))) {
    $r = ([string]$r).TrimEnd('\'); if ($r.Length -gt 3 -and -not ($PrivRoots | Where-Object { $_ -ieq $r })) { $PrivRoots += $r }
}
$PrivRoots = @($PrivRoots | Sort-Object Length -Descending)
# A private path is replaced whole, to the end of the path (a quote, a bracket, a bar or the line end): the folders after a
# user's folder can name a person or a company too (C:\Users\John Smith\Dropbox (Acme Corp)\x).
$PathTail = '[^\r\n"''<>|]*'
$UsersDirPattern = '(?i)(?:\b[a-z]:)?(?:\\\\|\\|/)+users(?:\\\\|\\|/)+(?!(?:public|shared|default|default user|all users)(?:\\\\|\\|/|[\r\n"''<>|]|$))' + $PathTail
$OneDrivePattern = '(?i)(?:\b[a-z]:|(?<![\w%])[\\/])[^\r\n"''<>|]*?onedrive' + $PathTail
$UncPattern = '(?<![:\\/\w])(?:\\\\\\\\|\\\\|//)[^\\/\s"''<>|%]+(?:\\\\|\\|/)[^\\/\s"''<>|]+' + $PathTail
function Scrub([string]$t) {   # private folders and any user's folder (whole path), network shares, OneDrive, and the private words
    if (-not $t) { return $t }
    foreach ($r in $PrivRoots) { foreach ($form in @($r, $r.Replace('\', '\\'), $r.Replace('\', '/'))) { $t = [regex]::Replace($t, [regex]::Escape($form) + $PathTail, '<private path>', 'IgnoreCase') } }
    $t = [regex]::Replace($t, $UncPattern, '<network path>')
    $t = [regex]::Replace($t, $UsersDirPattern, '<private path>')
    $t = [regex]::Replace($t, $OneDrivePattern, '<private path>')
    $t = [regex]::Replace($t, '(?i)onedrive', 'cloud drive')
    foreach ($w in $PrivWords) { $t = [regex]::Replace($t, '(?i)(?<![a-z0-9])' + [regex]::Escape($w) + '(?![a-z0-9])', '<name>') }
    return $t
}
$script:RunFolder = $null; $script:Swept = $false
function CrashSweep() {   # the run stopped early (an error or Ctrl+C): every file left in the run folder is checked, and no zip is made
    if ($script:Swept -or -not $script:RunFolder -or -not (Test-Path -LiteralPath $script:RunFolder)) { return }
    $script:Swept = $true
    $r = SweepFolder $script:RunFolder @()
    if ($r.stuck.Count) { Write-Host ('Privacy: ' + $r.stuck.Count + ' file(s) in the output folder hold a private path and could not be removed. Delete this folder, do not send it: ' + (Scrub $script:RunFolder)) -ForegroundColor Red }
    else { Write-Host ('The run stopped before the end. Every file left in the output folder was checked (' + $r.removed.Count + ' removed); no zip was made.') -ForegroundColor Yellow }
}
trap {   # an uncaught error: printed and logged scrubbed, never as PowerShell's own (unscrubbed) error record
    $e = $_.Exception; while ($e.InnerException) { $e = $e.InnerException }
    $msg = Scrub ('The Alibre Fixture Builder stopped: ' + $e.Message + ' (script line ' + $_.InvocationInfo.ScriptLineNumber + ')')
    if ($Log) { try { [IO.File]::AppendAllText($Log, $msg + "`r`n", $Utf8) } catch { } }
    Write-Host $msg -ForegroundColor Red
    CrashSweep
    exit 1
}
Add-Type -TypeDefinition @'
using System; using System.IO; using System.IO.Compression; using System.Text; using System.Text.RegularExpressions; using System.Collections.Generic;
public static class FixturePrivacy {
  // Text is compared lower-case with CR/LF removed (STEP wraps lines mid-path) and every backslash run read as one '/'.
  static string Norm(string s) { return Regex.Replace(s.ToLowerInvariant().Replace("\r", "").Replace("\n", ""), @"[\\/]+", "/"); }
  static Regex[] pats; static string[] kinds;
  public static void SetNeedles(string[] roots, string[] words) {
    var p = new List<Regex>(); var k = new List<string>();
    // the private folders (profile, Documents, Desktop, OneDrive), without the drive: Alibre also writes ":/Users/..."
    foreach (string root in roots) {
      string np = Norm(root ?? "").TrimEnd('/'); if (np.Length > 2 && np[1] == ':') np = np.Substring(2);
      if (np.Length > 3) { p.Add(new Regex(Regex.Escape(np) + "(?![a-z0-9])")); k.Add("a private folder path (profile, Documents, Desktop or OneDrive)"); }
    }
    // any user's folder (long or 8.3 name) but Public, Shared, Default, Default User and All Users
    p.Add(new Regex(@"/users/(?!(?:public|shared|default|default user|all users)(?![a-z0-9._~$ -]))[^/\s""'<>|:*?\x00-\x1f]")); k.Add("a user's folder path");
    // the user, profile-folder, computer and domain names: as a word anywhere (start of file, own line, after a tab, a quote or a
    // length byte) when four or more characters long, else inside a path
    foreach (string w in words) {
      if (string.IsNullOrEmpty(w)) continue; string e = Regex.Escape(w.ToLowerInvariant());
      p.Add(w.Length >= 4 ? new Regex("(?<![a-z0-9])" + e + "(?![a-z0-9])") : new Regex(@"[/:][^/\x00-\x1f""'<>|*?]*?(?<![a-z0-9])" + e + "(?![a-z0-9])"));
      k.Add("your user or computer name");
    }
    p.Add(new Regex("onedrive")); k.Add("a cloud-sync folder path");
    pats = p.ToArray(); kinds = k.ToArray();
  }
  // a file or folder name (relative to the run folder) with a private word or path
  public static string CheckName(string s) { string t = Norm("/" + s); for (int i = 0; i < pats.Length; i++) if (pats[i].IsMatch(t)) return kinds[i] + " (in its name)"; return null; }
  // 0: Latin-1 (any byte), 1 and 2: UTF-16LE at both byte alignments, 3: UTF-8 (a non-Latin name is found in every form),
  // 4 and 5: UTF-16BE at both alignments
  static string Text(byte[] b, int enc) {
    if (enc == 0) return Encoding.GetEncoding(28591).GetString(b);
    if (enc == 3) return Encoding.UTF8.GetString(b);
    int a = (enc == 2 || enc == 5) ? 1 : 0;
    if (b.Length < 2 + a) return "";
    return (enc >= 4 ? Encoding.BigEndianUnicode : Encoding.Unicode).GetString(b, a, (b.Length - a) & ~1);
  }
