function PrivatePathReason($p) {   # why a folder may not hold the output, or '' when it may
    $full = [IO.Path]::GetFullPath($p).TrimEnd('\')
    $prof = ([string]$env:USERPROFILE).TrimEnd('\')
    if ($prof -and ($full -ieq $prof -or $full.StartsWith($prof + '\', [StringComparison]::OrdinalIgnoreCase))) { return 'it is inside your user profile' }
    if ($full -match '(?i)^(?:[a-z]:|\\\\[^\\]+\\[^\\]+)\\users\\([^\\]+)' -and $Matches[1] -notmatch '^(?i)(public|shared|default|default user|all users)$') { return "it is inside a user's folder (C:\Users\<name>)" }
