    # a drive label or a share)
    $root = (Join-Path $(if ($env:PUBLIC) { $env:PUBLIC } else { 'C:\Users\Public' }) 'FixtureOut').TrimEnd('\')
    if (-not $full.StartsWith($root + '\', [StringComparison]::OrdinalIgnoreCase)) { return ('it is not inside ' + $root + ' (Alibre writes the output folder into every file it saves)') }
    if ($PrivUserOk) {
