    [IO.File]::WriteAllBytes((Join-Path $dir 'utf16odd.bin'), [byte[]](@(7) + [Text.Encoding]::Unicode.GetBytes('Q' + $prof + '\x')))   # UTF-16 text at an odd byte offset
    $ms = New-Object IO.MemoryStream; $zs = New-Object IO.Compression.DeflateStream($ms, [IO.Compression.CompressionMode]::Compress, $true); $ub = [byte[]](@(0) + [Text.Encoding]::Unicode.GetBytes('Q' + $prof + '\x')); $zs.Write($ub, 0, $ub.Length); $zs.Dispose()
    [IO.File]::WriteAllBytes((Join-Path $dir 'deflated16odd.bin'), [byte[]](@(1, 2, 3) + $ms.ToArray()))   # the same, odd-aligned inside a raw deflate stream
    Plant 'readonly.bin' ($prof + '\x'); [IO.File]::SetAttributes((Join-Path $dir 'readonly.bin'), [IO.FileAttributes]::ReadOnly)
    Plant 'locked.bin' ($prof + '\x')
    $hold = New-Object IO.FileStream((Join-Path $dir 'locked.bin'), [IO.FileMode]::Open, [IO.FileAccess]::ReadWrite, [IO.FileShare]::Delete)   # an antivirus-style lock: no one may read it
    $rows = @([pscustomobject]@{ id = 'short83'; status = 'ok'; error = ''; files = @('short83.bin') })
    $sr = SweepFolder $dir $rows
    $hold.Dispose()
    $PrivRoots = $savedRoots; [FixturePrivacy]::SetNeedles([string[]]$PrivRoots, [string[]]$PrivWords)
    $left = @(Get-ChildItem -LiteralPath $dir -File | ForEach-Object { $_.Name })
    Check 'removes an unlisted leftover file' ($left -notcontains 'leftover.tmp')
    Check "removes a file naming a user's 8.3 folder and fails its row" (($left -notcontains 'short83.bin') -and $rows[0].status -eq 'failed')
    if ($PrivUserOk) { Check 'removes a file with the user name inside a path component' ($left -notcontains 'component.bin') }
    Check 'scrubs a text file and keeps it' (($left -contains 'notes.txt') -and ([IO.File]::ReadAllText((Join-Path $dir 'notes.txt'), $Utf8)) -ceq 'saved to <private path>')
    Check 'keeps a clean file' ($left -contains 'clean.bin')
    Check 'removes a file with a redirected Documents path' ($left -notcontains 'redirected.bin')
    if (PrivWordOk $env:COMPUTERNAME) { Check 'removes a file with the computer name' ($left -notcontains 'host.bin') }
    if ($PrivWords.Count) { Check 'removes a file whose name holds a private word' (-not ($left | Where-Object { $_ -like 'named-*' })) }
    Check 'removes UTF-16BE text at an odd offset' ($left -notcontains 'utf16be.bin')
    if ($w4) {
        Check 'scrubs and keeps a text file with a private word alone on a line' (($left -contains 'word-line.txt') -and ([IO.File]::ReadAllText((Join-Path $dir 'word-line.txt'), $Utf8)) -ceq "abc`r`n<name>`r`nxyz")
        Check 'removes a file with a private word after a tab' ($left -notcontains 'word-tab.bin')
        Check 'scrubs a private word inside a JSON string' (([IO.File]::ReadAllText((Join-Path $dir 'word-quoted.json'), $Utf8)) -ceq '["<name>"]')
        Check 'removes a file with a private word after a length byte' ($left -notcontains 'word-lenbyte.bin')
        Check 'removes a file starting with a private word in UTF-16' ($left -notcontains 'word-start16.bin')
    } else { Write-Host 'SKIP 4+ character word cases: no private word of four or more characters here' }
    Check "removes another user's non-Latin folder in UTF-8" ($left -notcontains 'cyrillic-utf8.bin')
    Check "removes another user's non-Latin folder in UTF-16 at an odd offset" ($left -notcontains 'cyrillic-utf16odd.bin')
    Check 'removes a file whose compressed stream is too large to check (a cap is a hit)' ($left -notcontains 'too-large.bin')
    Check 'removes a compound file that cannot be read whole' ($left -notcontains 'broken.AD_PRT')
    $hs = [IO.File]::ReadAllText((Join-Path $dir 'header.step'))
    Check 'rewrites the STEP FILE_NAME to the bare name, author and organization empty' (($hs -match "/\* name \*/ 'header\.step',") -and ($hs -notmatch 'Acme|Doe') -and ($hs -match "2026-11-25T10:00:00"))
    Check 'keeps Default, All Users and Shared folders' ($left -contains 'exempt.bin')
    Check 'removes UTF-16 text at an odd byte offset' ($left -notcontains 'utf16odd.bin')
    Check 'removes odd-aligned UTF-16 inside a deflate stream' ($left -notcontains 'deflated16odd.bin')
    Check 'removes a read-only file' ($left -notcontains 'readonly.bin')
    Check 'removes a file it cannot read (a scan error fails closed)' ($left -notcontains 'locked.bin')
    Check 'leaves nothing it could not remove' ($sr.stuck.Count -eq 0)
    Remove-Item -LiteralPath $dir -Recurse -Force
    Write-Host ([string]$script:pass + ' passed, ' + $script:fail + ' failed')
    throw ('self-test of the console error path, from ' + $prof + '\Documents\x.AD_PRT')   # printed scrubbed by the trap
}
$Program = $null
foreach ($root in @($env:ProgramFiles, ${env:ProgramFiles(x86)})) {
